/**
 * The demo workspace: a handful of books at different stages, generated by simulation so they
 * always look realistic relative to "today" (PLAN §4.3). Titles and names are fictional.
 */
import { DEFAULT_CALENDAR, getCalendar } from '../calendar/calendar'
import type { IsoDate } from '../model/common'
import type { Person } from '../model/publication'
import { SCENARIOS } from '../simulation/library'
import { runScenario, type Scenario } from '../simulation/scenario'
import type { PublicationRecord } from './workspace'

export const DEMO_PEOPLE: Person[] = [
  { id: 'demo-anna', name: 'Anna Holm', email: null, defaultRoles: ['project-lead'] },
  { id: 'demo-sofie', name: 'Sofie Lund', email: null, defaultRoles: ['project-lead'] },
  { id: 'demo-mikkel', name: 'Mikkel Brandt', email: null, defaultRoles: ['editor'] },
  { id: 'demo-jonas', name: 'Jonas Kjær', email: null, defaultRoles: ['designer'] },
]

const library = (id: string) => {
  const s = SCENARIOS.find((x) => x.id === id)
  if (!s) throw new Error(`Unknown scenario ${id}`)
  return s
}

interface DemoBook {
  id: string
  title: string
  scenario: Scenario
  /** Working days from "today" to the desired release. */
  releaseInWorkdays: number
  projectLeadId: string
}

export const DEMO_BOOKS: DemoBook[] = [
  {
    // In print: everything has gone to plan.
    id: 'demo-kunstnerens-hus',
    title: 'Kunstnerens hus',
    scenario: library('on-plan'),
    releaseInWorkdays: 25,
    projectLeadId: 'demo-anna',
  },
  {
    // The image track overran badly: the release forecast has slipped.
    id: 'demo-industriens-arkitektur',
    title: 'Industriens arkitektur',
    scenario: {
      id: 'demo-images-late',
      name: 'Billedresearch og rettigheder trækker ud',
      description: 'Billedresearchen tager 6 uger længere end planlagt.',
      seed: 11,
      policy: { kind: 'custom', delays: { 'image-research': 30 }, base: 'realistic' },
      events: [],
    },
    releaseInWorkdays: 60,
    projectLeadId: 'demo-anna',
  },
  {
    // The author was 3 weeks late; the buffer took it.
    id: 'demo-fjordens-fugle',
    title: 'Fjordens fugle',
    scenario: library('author-3-weeks-late'),
    releaseInWorkdays: 95,
    projectLeadId: 'demo-sofie',
  },
  {
    // On HOLD right now, waiting for a funding decision.
    id: 'demo-den-danske-have',
    title: 'Den danske have',
    scenario: library('funding-hold-6-weeks'),
    releaseInWorkdays: 185,
    projectLeadId: 'demo-sofie',
  },
  {
    // Just started: before the GO decision.
    id: 'demo-nye-stemmer',
    title: 'Nye stemmer',
    scenario: library('realistic'),
    releaseInWorkdays: 225,
    projectLeadId: 'demo-anna',
  },
]

export interface DemoWorkspace {
  people: Person[]
  publications: PublicationRecord[]
}

/** Builds the demo workspace as it looks on `today`. Deterministic for a given date. */
export function seedDemoWorkspace(options: {
  today: IsoDate
  recordedAt: string
  newId: () => string
}): DemoWorkspace {
  const cal = getCalendar(DEFAULT_CALENDAR)
  const publications = DEMO_BOOKS.map((book) => {
    const run = runScenario(book.scenario, {
      releaseDate: cal.addWorkdays(options.today, book.releaseInWorkdays),
      until: options.today,
      recordedAt: options.recordedAt,
      newId: options.newId,
      publicationId: book.id,
      workingTitle: book.title,
      projectLeadId: book.projectLeadId,
    })
    return { publication: run.publication, history: run.history, simulation: run.simulation }
  })
  return { people: DEMO_PEOPLE, publications }
}
